/**
 * THE FACES
 *
 * Twenty-four painted busts on one sheet, keyed off magenta. The crew is
 * generated — names, wages, traits — so a face is chosen by hashing the member's
 * id: the same person keeps the same face for as long as they work for you, and
 * across a save and a reload, without storing anything.
 */
export const PEOPLE_COLS = 6;
export const PEOPLE_CELL = 160;
export const PEOPLE_COUNT = 24;

/** Same id, same face, every time — and no new field on the crew to persist. */
export const portraitIndex = (seed: string): number => {
  let h = 2166136261;
  for (let i = 0; i < seed.length; i++) { h ^= seed.charCodeAt(i); h = Math.imul(h, 16777619); }
  return Math.abs(h) % PEOPLE_COUNT;
};

export const PEOPLE_SHEET = "data:image/webp;base64,";
